const d = $input.item.json;
// Extraer texto limpio del HTML (primeros 600 chars)
const excerpt = (d.HTML_FINAL || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 600);
const lang = d.IDIOMA || 'es';
const es = lang === 'es';
return { json: {
  ID_UNICO: d.ID_UNICO,
  TEMA_ARTICULO: d.TEMA_ARTICULO,
  URL_FINAL: d.URL_FINAL,
  NICHO: d.NICHO || '',
  IDIOMA: lang,
  EXCERPT: excerpt,
  systemPrompt: es
    ? 'Eres experto en marketing de contenido y redes sociales. Respondes SOLO con JSON válido, sin markdown, sin comentarios.'
    : 'You are a social media marketing expert. Respond ONLY with valid JSON, no markdown, no comments.',
  userPrompt: es
    ? `Genera posts para redes sociales para este artículo:\nTítulo: "${d.TEMA_ARTICULO}"\nURL: ${d.URL_FINAL}\nNicho: ${d.NICHO || 'general'}\nResumen: ${excerpt.slice(0, 300)}\n\nResponde SOLO con este JSON:\n{"facebook": "post con emojis, 200-280 chars, CTA, 5 hashtags", "twitter": "tweet ≤270 chars con CTA y 3 hashtags", "instagram": "caption con emojis, 200-280 chars, 10 hashtags", "threads": "post conversacional ≤250 chars"}`
    : `Generate social media posts for:\nTitle: "${d.TEMA_ARTICULO}"\nURL: ${d.URL_FINAL}\nNiche: ${d.NICHO || 'general'}\nSummary: ${excerpt.slice(0, 300)}\n\nRespond ONLY with this JSON:\n{"facebook": "post with emojis, 200-280 chars, CTA, 5 hashtags", "twitter": "tweet ≤270 chars with CTA and 3 hashtags", "instagram": "caption with emojis, 200-280 chars, 10 hashtags", "threads": "conversational post ≤250 chars"}`
}};

const res = $('DeepSeek Generar Social').item.json;
const prev = $('Preparar Prompt Social').item.json;
if (!res.choices || !res.choices[0]) {
  throw new Error('DeepSeek sin respuesta social: ' + JSON.stringify(res).slice(0,200));
}
let social;
try {
  const raw = res.choices[0].message.content;
  const clean = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'').trim();
  social = JSON.parse(clean);
} catch(e) {
  throw new Error('JSON inválido de DeepSeek social: ' + e.message);
}
// Añadir URL al texto si no está presente
const url = prev.URL_FINAL || '';
const addUrl = (text) => text && !text.includes(url.slice(0,20)) ? text + '\n' + url : text;
return { json: {
  ID_UNICO:          prev.ID_UNICO,
  TEMA_ARTICULO:     prev.TEMA_ARTICULO,
  URL_FINAL:         prev.URL_FINAL,
  NICHO:             prev.NICHO,
  FACEBOOK_POST:     addUrl(social.facebook  || ''),
  TWITTER_POST:      addUrl(social.twitter   || '').slice(0, 280),
  INSTAGRAM_CAPTION: social.instagram        || '',
  THREADS_POST:      addUrl(social.threads   || '').slice(0, 500),
  GENERATED_AT:      new Date().toISOString()
}};

// Si DeepSeek falló, usar contenido básico generado localmente
const prev = $('Preparar Prompt Social').item.json;
const url = prev.URL_FINAL || '';
const title = prev.TEMA_ARTICULO || '';
const niche = prev.NICHO || '';
return { json: {
  ID_UNICO:          prev.ID_UNICO,
  TEMA_ARTICULO:     title,
  URL_FINAL:         url,
  NICHO:             niche,
  FACEBOOK_POST:     `📝 ${title}\n\n${prev.EXCERPT ? prev.EXCERPT.slice(0,180) : ''}...\n\n🔗 ${url}\n\n#${niche}`,
  TWITTER_POST:      `${title.slice(0,200)} 🔗 ${url}`.slice(0,280),
  INSTAGRAM_CAPTION: `${title}\n\n${prev.EXCERPT ? prev.EXCERPT.slice(0,180) : ''}\n\n#${niche}`,
  THREADS_POST:      `${title.slice(0,200)} → ${url}`.slice(0,500),
  GENERATED_AT:      new Date().toISOString(),
  IS_FALLBACK:       true
}};
